use vstd::prelude::*;

verus! {
    fn reverse(a: &Vec<char>) -> Vec<char>
        requires
            a.len() > 0, // The input vector must be non-empty
        ensures
            result.len() == a.len(), // The output vector has the same length as the input
            forall |k: nat| 0 <= k < result.len() ==> result[k] == a[(a.len() - 1 - k) as usize], // Output is reversed
        ensures
            a == *a, // The input vector is not modified
    {
        let mut result: Vec<char> = Vec::new();
        let n = a.len();
        result.resize(n, ' '); // Resize the result vector to the same length as input

        let mut i: usize = 0;
        while i < n
            invariant
                i <= n, // i is within bounds
                result.len() == n, // The output vector has the same length as input
                forall |j: nat| 0 <= j < i ==> result[j] == a[(n - 1 - j) as usize], // Elements filled correctly so far
            decreases n - i, // Decreases clause to ensure termination
        {
            result[i] = a[(n - 1 - i) as usize]; // Fill the result vector with reversed elements
            i = i + 1; // Increment the index
        }
        result // Return the reversed vector
    }
}
